// removeAgentHooks removes hooks from all agents that support hooks.
func removeAgentHooks(ctx context.Context, w io.Writer) error {
	var errs []error
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
